        const handleLog = (arg1, arg2) => {
            const data = (arg1 && (arg1.promptId !== undefined || arg1.status !== undefined || arg1.videoUrl !== undefined || arg1.message !== undefined)) ? arg1 : (arg2 || arg1);
            if (!data) return;
            console.log("[Commerce Log Received]", data);
            if (data.promptId !== undefined) {
                setTasks(prev => prev.map(t => {
                    if (t.id === data.promptId || String(t.id) === String(data.promptId)) {
                        return {
                            ...t,
                            status: data.status || t.status,
                            message: data.message || t.message,
                            videoUrl: data.videoUrl || t.videoUrl,
                            generatedImageUrl: data.thumbnail || data.generatedImageUrl || t.generatedImageUrl
                        };
                    }
                    return t;
                }));
            }
            if (data.status === 'idle' || data.status === 'finished') {
                setIsRunning(false);
            }
        };
        const removeListener = window.electronAPI.onBrowserLog(handleLog);

        // --- BỔ SUNG: LOAD TASKS KHI MOUNT ---
