const api_Thumb = async (t, e, s = {}) => {
    if (!window.electronAPI) throw new Error("Electron API missing");
    return window.electronAPI.fetch(t, e || { id: "", name: "", value: "" }, s);
};

const getCookieFromServer = async (t, reason = "") => {
    const r = String(reason || "").trim();
    const url = (r === "401" || r === "429")
        ? `https://tainguyenweb.com/apiveo/kinxcookie.php?${r}`
        : "https://tainguyenweb.com/apiveo/kinxcookie.php";
    const e = await api_Thumb(url, null, { method: "GET", headers: { "X-API-Key": "kinx@0$*2048", Authorization: `Bearer ${t}` } });
    if (!e.success || !e.cookie?.value) {
        try {
            const e2 = await api_Thumb(url, null, { method: "GET", headers: { "X-API-Key": "kinx@0$*2048", Authorization: `Bearer ${t}` } });
            if (e2.success && e2.cookie?.value) {
                return { ...e2.cookie, bearerToken: e2.cookie.bearerToken || "FLOW_SESSION" };
            }
        } catch { }
        throw new Error("Lỗi lấy cookie từ server. Vui lòng kiểm tra kết nối hoặc tài khoản.");
    }
    return { ...e.cookie, bearerToken: e.cookie.bearerToken || "FLOW_SESSION" };
};

const getSmartCookie = async (token, activeCookie) => {
    if (activeCookie && activeCookie.value) return { ...activeCookie, bearerToken: activeCookie.bearerToken || "FLOW_SESSION" };
    return await getCookieFromServer(token);
};

const gen_Banana_Pro = async (cookie, s, i, aspect, imageBase64 = null, allowText = false, projectIdOverride = null, returnMediaId = false, modelNameOverride = "GEM_PIX_2") => {
    const projectId = projectIdOverride || crypto.randomUUID();
    // const url = `https://aisandbox-pa.googleapis.com/v1/projects/${projectId}/flowMedia:batchGenerateImages`;
    const url = `https://flow.google.com/v1/projects/${projectId}/flowMedia:batchGenerateImages`;
    let imageInputs = [];
    if (imageBase64) {
        try {
            // Existing media IDs are references, not image bytes.
            if (typeof imageBase64 !== "string" || !imageBase64.startsWith("data:")) {
                if (typeof imageBase64 === "string" && imageBase64.trim()) {
                    imageInputs.push({ name: imageBase64.trim(), imageInputType: "IMAGE_INPUT_TYPE_REFERENCE" });
                }
            } else {
                // Giữ nguyên định dạng gốc, bóc tách chuẩn xác MimeType và Đuôi File
                const mimeMatch = imageBase64.match(/^data:(image\/\w+);base64,/);
                const dynamicMimeType = mimeMatch ? mimeMatch[1] : "image/jpeg";
                const ext = dynamicMimeType.split('/')[1] || 'jpg';
                const rawBytes = imageBase64.replace(/^data:[^;]+;base64,/, "");
                const fileName = `upload_${Date.now()}.${ext}`;

                // const uploadRes = await api_Thumb("https://aisandbox-pa.googleapis.com/v1/flow/uploadImage", cookie, {
                const uploadRes = await api_Thumb("https://flow.google.com/v1/flow/uploadImage", cookie, {
                    method: "POST",
                    body: JSON.stringify({
                        clientContext: { projectId: projectId, tool: "IMAGE_FX" },
                        imageBytes: rawBytes,
                        isUserUploaded: true,
                        isHidden: false,
                        mimeType: dynamicMimeType,
                        fileName: fileName
                    }),
                    headers: { "Content-Type": "text/plain;charset=UTF-8" },
                });
                const mediaId = uploadRes?.media?.name || uploadRes?.mediaGenerationId?.mediaGenerationId || uploadRes?.name || uploadRes?.id;
                if (mediaId) imageInputs.push({ name: mediaId, imageInputType: "IMAGE_INPUT_TYPE_REFERENCE" });
            }
        } catch (e) {
            console.error("Upload image error:", e);
            if (/401|429|unauthenticated|unauthorized|snlm0e|hết hạn|quota|resource_exhausted|bearer token/i.test(String(e?.message || ""))) throw e;
        }
    }
    const noTextRule = "\n\nCRITICAL RULE: DO NOT render any text, letters, words, signatures, labels, or watermarks in this image. The image must be completely text-free.";
    const payload = {
        clientContext: { sessionId: `;${Date.now()}`, tool: "IMAGE_FX", projectId: projectId },
        mediaGenerationContext: { batchId: crypto.randomUUID() },
        useNewMedia: true,
        requests: [{
            clientContext: { sessionId: `;${Date.now()}`, tool: "IMAGE_FX", projectId: projectId },
            seed: i,
            prompt: s,
            imageModelName: modelNameOverride || "GEM_PIX_2",
            imageAspectRatio: `IMAGE_ASPECT_RATIO_${aspect || "LANDSCAPE"}`,
            structuredPrompt: { parts: [{ text: s }] },
            imageInputs: imageInputs
        }],
    };
    const g = await api_Thumb(url, cookie, { method: "POST", body: JSON.stringify(payload), headers: { "Content-Type": "application/json" } });
    let v = g?.media?.[0]?.image?.generatedImage?.encodedImage;
    if (!v && g?.media?.[0]?.image?.generatedImage?.fifeUrl) {
        try {
            const imgRes = await fetch(g.media[0].image.generatedImage.fifeUrl);
            const imgBuffer = await imgRes.arrayBuffer();
            const bytes = new Uint8Array(imgBuffer);
            let binary = "";
            for (let idx = 0; idx < bytes.byteLength; idx++) binary += String.fromCharCode(bytes[idx]);
            v = btoa(binary);
        } catch (err) { }
    }
    if (!v) v = g?.media?.[0]?.image?.encodedImage;
    if (!v) v = g?.image?.encodedImage;
    if (!v || v === "undefined" || v === "null") throw new Error(g?.error?.message || "Banana Pro error: No image found in response.");
    if (returnMediaId) {
        const mediaId = g?.media?.[0]?.name || g?.media?.[0]?.image?.generatedImage?.name || g?.mediaGenerationId?.mediaGenerationId || g?.name || null;
        return { base64: v, mediaId };
    }
    return v;
};
